@Repository
public interface UserRepository extends JpaRepository<User, Long> {

    // 1. JPQL Query with Named Parameters
    @Query("SELECT u FROM User u JOIN FETCH u.roles WHERE u.status = :status")
    List<User> findActiveUsersWithRoles(@Param("status") UserStatus status);

    // 2. Native Query with DTO Projection
    @Query(value = "SELECT u.id AS id, u.username AS username FROM users u WHERE u.created_date >= :startDate", nativeQuery = true)
    List<UserSummaryDto> findRecentUsersNative(@Param("startDate") LocalDate startDate);
}

// 3. Criteria API Dynamic Query Example
@Service
public class UserSearchService {
    @PersistenceContext
    private EntityManager em;

    public List<User> searchUsers(String name, UserStatus status) {
        CriteriaBuilder cb = em.getCriteriaBuilder();
        CriteriaQuery<User> cq = cb.createQuery(User.class);
        Root<User> user = cq.from(User.class);

        List<Predicate> predicates = new ArrayList<>();
        if (name != null) {
            predicates.add(cb.like(user.get(User_.username), "%" + name + "%"));
        }
        if (status != null) {
            predicates.add(cb.equal(user.get(User_.status), status));
        }

        cq.where(predicates.toArray(new Predicate[0]));
        return em.createQuery(cq).getResultList();
    }
}
